     9	import com.fasterxml.jackson.core.JsonProcessingException;
    10	import com.fasterxml.jackson.databind.ObjectMapper;
    11	import io.javalin.Javalin;
    12	import io.javalin.http.Context;
    13	
    14	import java.util.List;
    15	
    16	public class Api {
    17	    private final ReservationService service;
    18	    private final Reports reports;
    19	    private final MessageRepository messages;
    20	    private final ObjectMapper mapper = new ObjectMapper();
    21	    private final RequestParser parser = new RequestParser(mapper);
    22	
    23	    public Api(ReservationService service, Reports reports, MessageRepository messages) {
    24	        this.service = service;
    25	        this.reports = reports;
    26	        this.messages = messages;
    27	    }
    28	
    29	    public Javalin create() {
    30	        Javalin app = Javalin.create(config -> config.showJavalinBanner = false);
    31	
    32	        app.exception(DomainException.class, (e, ctx) -> error(ctx, e.code(), e.getMessage()));
    33	        app.exception(Exception.class, (e, ctx) -> {
    34	            e.printStackTrace();
    35	            ctx.status(500);
    36	            send(ctx, 500, new Views.ErrorView("INTERNAL_ERROR", "Erro interno"));
    37	        });
    38	
    39	        app.get("/rooms", ctx -> send(ctx, 200, service.rooms().stream().map(Views.RoomView::of).toList()));
    40	        app.post("/reservations", ctx -> send(ctx, 201,
    41	                Views.ReservationView.of(service.create(parser.newReservation(ctx.body())))));
    42	        app.get("/reservations/{id}", ctx -> send(ctx, 200, Views.ReservationView.of(service.get(id(ctx)))));
    43	        app.post("/reservations/{id}/confirmation", ctx ->
    44	                send(ctx, 200, Views.ReservationView.of(service.confirm(id(ctx)))));
    45	        app.post("/reservations/{id}/cancellation", ctx ->
    46	                send(ctx, 200, Views.ReservationView.of(service.cancel(id(ctx)))));
    47	        app.post("/reservations/{id}/check-in", ctx ->
    48	                send(ctx, 200, Views.ReservationView.of(service.checkIn(id(ctx)))));
    49	        app.post("/reservations/{id}/check-out", ctx ->
    50	                send(ctx, 200, Views.ReceiptView.of(service.checkOut(id(ctx)))));
    51	        app.get("/reservations/{id}/document", ctx ->
    52	                send(ctx, 200, Views.ReceiptView.of(service.document(id(ctx)))));
    53	        app.get("/messages", ctx -> {
    54	            List<Message> all = messages.findAll();
    55	            send(ctx, 200, all);
    56	        });
    57	        app.get("/reports/occupancy", ctx -> csv(ctx,
    58	                reports.occupancy(parser.date(ctx.queryParam("date"), "date"))));
    59	        app.get("/reports/revenue", ctx -> csv(ctx, reports.revenue(parser.month(ctx.queryParam("month")))));
    60	        return app;
    61	    }
    62	
    63	    private long id(Context ctx) {
    64	        try {
    65	            return Long.parseLong(ctx.pathParam("id"));
    66	        } catch (NumberFormatException e) {
    67	            throw new DomainException(ErrorCode.RESERVATION_NOT_FOUND, "Reserva não encontrada");
    68	        }
    69	    }
    70	
    71	    private void error(Context ctx, ErrorCode code, String message) {
    72	        send(ctx, code.httpStatus(), new Views.ErrorView(code.name(), message));
    73	    }
    74	
    75	    private void send(Context ctx, int status, Object body) {
    76	        try {
    77	            ctx.status(status).contentType("application/json; charset=utf-8")
    78	                    .result(mapper.writeValueAsString(body));
    79	        } catch (JsonProcessingException e) {
    80	            throw new IllegalStateException(e);
    81	        }
    82	    }
    83	
    84	    private void csv(Context ctx, String content) {
    85	        ctx.status(200).contentType("text/csv; charset=utf-8").result(content);
    86	    }
    87	}
