     6	/** Avisa o financeiro dos pagamentos recebidos e dos reembolsos a fazer. */
     7	public class FinanceNotifier implements ReservationListener {
     8	    private final MessageLog log;
     9	    private final String address;
    10	
    11	    public FinanceNotifier(MessageLog log, String address) {
    12	        this.log = log;
    13	        this.address = address;
    14	    }
    15	
    16	    @Override
    17	    public void onConfirmed(ReservationConfirmed event) {
    18	        Reservation r = event.reservation();
    19	        String body = "Pagamento recebido da reserva nº " + r.id() + " (" + r.guestName() + "): "
    20	                + Money.brl(r.amountPaid()) + ".";
    21	        log.sendEmail(address, "Pagamento recebido - reserva " + r.id(), body);
    22	    }
    23	
    24	    @Override
    25	    public void onCancelled(ReservationCancelled event) {
    26	        Reservation r = event.reservation();
    27	        if (r.refund() == null || r.refund().signum() <= 0) {
    28	            return;
    29	        }
    30	        String body = "A reserva nº " + r.id() + " (" + r.guestName() + ") foi cancelada. "
    31	                + "Valor a devolver: " + Money.brl(r.refund()) + ".";
    32	        log.sendEmail(address, "Reembolso - reserva " + r.id(), body);
    33	    }
    34	}
