    10	
    11	import java.time.LocalDate;
    12	import java.time.YearMonth;
    13	import java.time.format.DateTimeParseException;
    14	
    15	/** Valida o que chega do site e transforma em comandos do sistema; qualquer defeito vira INVALID_REQUEST. */
    16	final class RequestParser {
    17	    private final ObjectMapper mapper;
    18	
    19	    RequestParser(ObjectMapper mapper) {
    20	        this.mapper = mapper;
    21	    }
    22	
    23	    NewReservation newReservation(String body) {
    24	        JsonNode json;
    25	        try {
    26	            json = mapper.readTree(body);
    27	        } catch (JsonProcessingException e) {
    28	            throw invalid("O corpo precisa ser um JSON válido");
    29	        }
    30	        if (json == null || !json.isObject()) {
    31	            throw invalid("O corpo precisa ser um objeto JSON");
    32	        }
    33	        return new NewReservation(
    34	                integer(json, "roomNumber"),
    35	                text(json, "guestName"),
    36	                text(json, "guestEmail"),
    37	                text(json, "guestCpf"),
    38	                date(text(json, "checkIn"), "checkIn"),
    39	                date(text(json, "checkOut"), "checkOut"),
    40	                integer(json, "guests"),
    41	                ratePlan(text(json, "ratePlan")));
    42	    }
    43	
    44	    LocalDate date(String value, String field) {
    45	        if (value == null) {
    46	            throw invalid("Informe " + field + " no formato aaaa-mm-dd");
    47	        }
    48	        try {
    49	            return LocalDate.parse(value);
    50	        } catch (DateTimeParseException e) {
    51	            throw invalid("Data inválida em " + field + ": use o formato aaaa-mm-dd");
    52	        }
    53	    }
    54	
    55	    YearMonth month(String value) {
    56	        if (value == null) {
    57	            throw invalid("Informe month no formato aaaa-mm");
    58	        }
    59	        try {
    60	            return YearMonth.parse(value);
    61	        } catch (DateTimeParseException e) {
    62	            throw invalid("Mês inválido: use o formato aaaa-mm");
    63	        }
    64	    }
    65	
    66	    private RatePlan ratePlan(String value) {
    67	        try {
    68	            return RatePlan.valueOf(value);
    69	        } catch (IllegalArgumentException e) {
    70	            throw invalid("ratePlan inválido: use STANDARD ou NON_REFUNDABLE");
    71	        }
    72	    }
    73	
    74	    private String text(JsonNode json, String field) {
    75	        JsonNode node = json.get(field);
    76	        if (node == null || !node.isTextual() || node.asText().isBlank()) {
    77	            throw invalid("Informe " + field);
    78	        }
    79	        return node.asText();
    80	    }
    81	
    82	    private int integer(JsonNode json, String field) {
    83	        JsonNode node = json.get(field);
    84	        if (node == null || !node.isIntegralNumber() || !node.canConvertToInt()) {
    85	            throw invalid("Informe " + field + " como número inteiro");
    86	        }
    87	        return node.asInt();
    88	    }
    89	
    90	    private static DomainException invalid(String message) {
    91	        return new DomainException(ErrorCode.INVALID_REQUEST, message);
    92	    }
    93	}
