    20	public class ReservationService {
    21	    private final Database db;
    22	    private final RoomRepository rooms;
    23	    private final ReservationRepository reservations;
    24	    private final List<ReservationListener> listeners;
    25	
    26	    public ReservationService(Database db, RoomRepository rooms, ReservationRepository reservations,
    27	                              List<ReservationListener> listeners) {
    28	        this.db = db;
    29	        this.rooms = rooms;
    30	        this.reservations = reservations;
    31	        this.listeners = List.copyOf(listeners);
    32	    }
    33	
    34	    public Reservation create(NewReservation request) {
    35	        if (request.guests() < 1) {
    36	            throw new DomainException(ErrorCode.INVALID_REQUEST, "É preciso ao menos um hóspede");
    37	        }
    38	        if (!request.checkOut().isAfter(request.checkIn())) {
    39	            throw new DomainException(ErrorCode.INVALID_REQUEST, "A saída deve ser depois da entrada");
    40	        }
    41	        return db.inTransaction(() -> {
    42	            Room room = rooms.findForUpdate(request.roomNumber()).orElseThrow(() ->
    43	                    new DomainException(ErrorCode.ROOM_NOT_FOUND, "Quarto não encontrado: " + request.roomNumber()));
    44	            if (request.guests() > room.capacity()) {
    45	                throw new DomainException(ErrorCode.CAPACITY_EXCEEDED,
    46	                        "O quarto " + room.number() + " comporta no máximo " + room.capacity() + " hóspedes");
    47	            }
    48	            if (reservations.hasActiveOverlap(room.number(), request.checkIn(), request.checkOut())) {
    49	                throw new DomainException(ErrorCode.ROOM_UNAVAILABLE,
    50	                        "O quarto " + room.number() + " já está reservado em alguma das noites pedidas");
    51	            }
    52	            Quote quote = Quote.of(room, request.checkIn(), request.checkOut(), request.ratePlan());
    53	            Reservation reservation = Reservation.pending(room.number(), request.guestName(),
    54	                    request.guestEmail(), request.guestCpf(), request.checkIn(), request.checkOut(),
    55	                    request.guests(), request.ratePlan(), quote);
    56	            reservations.insert(reservation);
    57	            return reservation;
    58	        });
    59	    }
    60	
    61	    public Reservation get(long id) {
    62	        return db.inTransaction(() -> reservations.find(id).orElseThrow(() -> notFound(id)));
    63	    }
    64	
    65	    public Reservation confirm(long id) {
    66	        return change(id, Reservation::confirm, (reservation, room) -> {
    67	            ReservationConfirmed event = new ReservationConfirmed(reservation, room);
    68	            listeners.forEach(listener -> listener.onConfirmed(event));
    69	        });
    70	    }
    71	
    72	    public Reservation cancel(long id) {
    73	        return change(id, Reservation::cancel, (reservation, room) -> {
    74	            ReservationCancelled event = new ReservationCancelled(reservation, room);
    75	            listeners.forEach(listener -> listener.onCancelled(event));
    76	        });
    77	    }
    78	
    79	    public Reservation checkIn(long id) {
    80	        return change(id, Reservation::registerCheckIn, (reservation, room) -> { });
    81	    }
    82	
    83	    public Receipt checkOut(long id) {
    84	        return db.inTransaction(() -> {
    85	            Reservation reservation = reservations.findForUpdate(id).orElseThrow(() -> notFound(id));
    86	            reservation.registerCheckOut();
    87	            reservations.update(reservation);
    88	            return Receipt.of(reservation, roomOf(reservation));
    89	        });
    90	    }
    91	
    92	    public Receipt document(long id) {
    93	        return db.inTransaction(() -> {
    94	            Reservation reservation = reservations.find(id).orElseThrow(() -> notFound(id));
    95	            reservation.requireReceipt();
    96	            return Receipt.of(reservation, roomOf(reservation));
    97	        });
    98	    }
    99	
   100	    public List<Room> rooms() {
   101	        return rooms.findAll();
   102	    }
   103	
   104	    private Reservation change(long id, Consumer<Reservation> transition,
   105	                               BiConsumer<Reservation, Room> announcement) {
   106	        return db.inTransaction(() -> {
   107	            Reservation reservation = reservations.findForUpdate(id).orElseThrow(() -> notFound(id));
   108	            transition.accept(reservation);
   109	            reservations.update(reservation);
   110	            announcement.accept(reservation, roomOf(reservation));
   111	            return reservation;
   112	        });
   113	    }
   114	
   115	    private Room roomOf(Reservation reservation) {
   116	        return rooms.find(reservation.roomNumber()).orElseThrow();
   117	    }
   118	
   119	    private static DomainException notFound(long id) {
   120	        return new DomainException(ErrorCode.RESERVATION_NOT_FOUND, "Reserva não encontrada: " + id);
   121	    }
   122	}
