     8	
     9	/** Acesso ao PostgreSQL: uma transação por operação, compartilhada pelos repositórios da mesma thread. */
    10	public final class Database {
    11	    private static final String SCHEMA = """
    12	            CREATE TABLE IF NOT EXISTS rooms (
    13	                number        INTEGER PRIMARY KEY,
    14	                type          TEXT NOT NULL,
    15	                capacity      INTEGER NOT NULL,
    16	                nightly_rate  NUMERIC(12,2) NOT NULL
    17	            );
    18	            CREATE TABLE IF NOT EXISTS reservations (
    19	                id            BIGSERIAL PRIMARY KEY,
    20	                room_number   INTEGER NOT NULL REFERENCES rooms(number),
    21	                guest_name    TEXT NOT NULL,
    22	                guest_email   TEXT NOT NULL,
    23	                guest_cpf     TEXT NOT NULL,
    24	                check_in      DATE NOT NULL,
    25	                check_out     DATE NOT NULL,
    26	                guests        INTEGER NOT NULL,
    27	                rate_plan     TEXT NOT NULL,
    28	                nights        INTEGER NOT NULL,
    29	                subtotal      NUMERIC(12,2) NOT NULL,
    30	                discount      NUMERIC(12,2) NOT NULL,
    31	                total         NUMERIC(12,2) NOT NULL,
    32	                status        TEXT NOT NULL,
    33	                amount_paid   NUMERIC(12,2) NOT NULL,
    34	                refund        NUMERIC(12,2)
    35	            );
    36	            CREATE INDEX IF NOT EXISTS reservations_room_idx ON reservations (room_number, check_in);
    37	            CREATE TABLE IF NOT EXISTS messages (
    38	                id         BIGSERIAL PRIMARY KEY,
    39	                channel    TEXT NOT NULL,
    40	                recipient  TEXT NOT NULL,
    41	                subject    TEXT NOT NULL,
    42	                body       TEXT NOT NULL
    43	            );
    44	            """;
    45	
    46	    private final String url;
    47	    private final String user;
    48	    private final String password;
    49	    private final ThreadLocal<Connection> current = new ThreadLocal<>();
    50	
    51	    public Database(String url, String user, String password) {
    52	        this.url = url;
    53	        this.user = user;
    54	        this.password = password;
    55	    }
    56	
    57	    /** Cria as tabelas, esperando o banco ficar disponível se ele ainda estiver subindo. */
    58	    public void initialize() {
    59	        SQLException last = null;
    60	        for (int attempt = 0; attempt < 30; attempt++) {
    61	            try (Connection connection = DriverManager.getConnection(url, user, password);
    62	                 Statement statement = connection.createStatement()) {
    63	                statement.execute("SELECT pg_advisory_lock(7070)");
    64	                try {
    65	                    statement.execute(SCHEMA);
    66	                } finally {
    67	                    statement.execute("SELECT pg_advisory_unlock(7070)");
    68	                }
    69	                return;
    70	            } catch (SQLException e) {
    71	                last = e;
    72	                try {
    73	                    Thread.sleep(1000);
    74	                } catch (InterruptedException ie) {
    75	                    Thread.currentThread().interrupt();
    76	                    break;
    77	                }
    78	            }
    79	        }
    80	        throw new DatabaseException("Não foi possível preparar o banco de dados", last);
    81	    }
    82	
    83	    public Connection connection() {
    84	        Connection connection = current.get();
    85	        if (connection == null) {
    86	            throw new IllegalStateException("Sem transação ativa");
    87	        }
    88	        return connection;
    89	    }
    90	
    91	    public <T> T inTransaction(Supplier<T> work) {
    92	        if (current.get() != null) {
    93	            return work.get();
    94	        }
    95	        try (Connection connection = DriverManager.getConnection(url, user, password)) {
    96	            connection.setAutoCommit(false);
    97	            current.set(connection);
    98	            try {
    99	                T result = work.get();
   100	                connection.commit();
   101	                return result;
   102	            } catch (RuntimeException e) {
   103	                connection.rollback();
   104	                throw e;
   105	            } finally {
   106	                current.remove();
   107	            }
   108	        } catch (SQLException e) {
   109	            throw new DatabaseException("Erro no banco de dados", e);
   110	        }
   111	    }
   112	}
