384	    57	    /** Cria as tabelas, esperando o banco ficar disponível se ele ainda estiver subindo. */
385	    58	    public void initialize() {
386	    59	        SQLException last = null;
387	    60	        for (int attempt = 0; attempt < 30; attempt++) {
388	    61	            try (Connection connection = DriverManager.getConnection(url, user, password);
389	    62	                 Statement statement = connection.createStatement()) {
390	    63	                statement.execute("SELECT pg_advisory_lock(7070)");
391	    64	                try {
392	    65	                    statement.execute(SCHEMA);
393	    66	                } finally {
394	    67	                    statement.execute("SELECT pg_advisory_unlock(7070)");
395	    68	                }
396	    69	                return;
397	    70	            } catch (SQLException e) {
398	    71	                last = e;
399	    72	                try {
400	    73	                    Thread.sleep(1000);
401	    74	                } catch (InterruptedException ie) {
402	    75	                    Thread.currentThread().interrupt();
403	    76	                    break;
404	    77	                }
405	    78	            }
406	    79	        }
407	    80	        throw new DatabaseException("Não foi possível preparar o banco de dados", last);
408	    81	    }
409	    82	
410	    83	    public Connection connection() {
411	    84	        Connection connection = current.get();
412	    85	        if (connection == null) {
413	    86	            throw new IllegalStateException("Sem transação ativa");
414	    87	        }
415	    88	        return connection;
416	    89	    }
