418	    91	    public <T> T inTransaction(Supplier<T> work) {
419	    92	        if (current.get() != null) {
420	    93	            return work.get();
421	    94	        }
422	    95	        try (Connection connection = DriverManager.getConnection(url, user, password)) {
423	    96	            connection.setAutoCommit(false);
424	    97	            current.set(connection);
425	    98	            try {
426	    99	                T result = work.get();
427	   100	                connection.commit();
428	   101	                return result;
429	   102	            } catch (RuntimeException e) {
430	   103	                connection.rollback();
431	   104	                throw e;
432	   105	            } finally {
433	   106	                current.remove();
434	   107	            }
435	   108	        } catch (SQLException e) {
436	   109	            throw new DatabaseException("Erro no banco de dados", e);
437	   110	        }
438	   111	    }
