 24	/** Roda contra o PostgreSQL de DB_URL, num schema próprio que é apagado no fim. */
 25	class ApiIntegrationTest {
 26	    private static final ObjectMapper MAPPER = new ObjectMapper();
 27	    private static final HttpClient HTTP = HttpClient.newHttpClient();
 28	    private static String schema;
 29	    private static String baseUrl;
 30	    private static Javalin app;
 31	
 32	    @BeforeAll
 33	    static void start() throws Exception {
 34	        String url = System.getenv("DB_URL");
 35	        Assumptions.assumeTrue(url != null, "DB_URL não definido");
 36	        schema = "test_" + UUID.randomUUID().toString().replace("-", "");
 37	        try (Connection c = DriverManager.getConnection(url, System.getenv("DB_USER"), System.getenv("DB_PASSWORD"));
 38	             Statement s = c.createStatement()) {
 39	            s.execute("CREATE SCHEMA " + schema);
 40	        }
 41	        String schemaUrl = url + (url.contains("?") ? "&" : "?") + "currentSchema=" + schema;
 42	        app = Main.build(new Database(schemaUrl, System.getenv("DB_USER"), System.getenv("DB_PASSWORD")));
 43	        app.start(0);
 44	        baseUrl = "http://localhost:" + app.port();
 45	    }
 46	
 47	    @AfterAll
 48	    static void stop() throws Exception {
 49	        if (app != null) {
 50	            app.stop();
 51	            try (Connection c = DriverManager.getConnection(System.getenv("DB_URL"), System.getenv("DB_USER"),
 52	                    System.getenv("DB_PASSWORD")); Statement s = c.createStatement()) {
 53	                s.execute("DROP SCHEMA " + schema + " CASCADE");
 54	            }
 55	        }
 56	    }
 57	
 58	    private static HttpResponse<String> call(String method, String path, String body) throws Exception {
 59	        HttpRequest.Builder b = HttpRequest.newBuilder(URI.create(baseUrl + path));
 60	        b.method(method, body == null ? HttpRequest.BodyPublishers.noBody() : HttpRequest.BodyPublishers.ofString(body));
 61	        return HTTP.send(b.build(), HttpResponse.BodyHandlers.ofString());
 62	    }
 63	
 64	    private static String reservation(int room, String in, String out, int guests, String plan) {
 65	        return """
 66	                {"roomNumber":%d,"guestName":"Carla Dias","guestEmail":"carla@example.com",
 67	                 "guestCpf":"111.222.333-44","checkIn":"%s","checkOut":"%s","guests":%d,"ratePlan":"%s"}"""
 68	                .formatted(room, in, out, guests, plan);
 69	    }
 70	
 71	    private static JsonNode create(int room, String in, String out, int guests, String plan) throws Exception {
 72	        HttpResponse<String> r = call("POST", "/reservations", reservation(room, in, out, guests, plan));
 73	        assertEquals(201, r.statusCode(), r.body());
 74	        return MAPPER.readTree(r.body());
 75	    }
 76	
 77	    private static String errorOf(HttpResponse<String> r) throws Exception {
 78	        return MAPPER.readTree(r.body()).get("error").asText();
 79	    }
