 81	    @Test
 82	    void roomsAreListed() throws Exception {
 83	        JsonNode rooms = MAPPER.readTree(call("GET", "/rooms", null).body());
 84	        assertEquals(5, rooms.size());
 85	        assertEquals(389.90, rooms.get(2).get("nightlyRate").asDouble());
 86	    }
