 88	    @Test
 89	    void confirmationNotifiesGuestHousekeepingAndFinance() throws Exception {
 90	        JsonNode created = create(201, "2030-03-10", "2030-03-12", 2, "STANDARD");
 91	        long id = created.get("id").asLong();
 92	        assertEquals("PENDING", created.get("status").asText());
 93	        assertTrue(created.get("refund").isNull());
 94	        int before = MAPPER.readTree(call("GET", "/messages", null).body()).size();
 95	
 96	        JsonNode confirmed = MAPPER.readTree(call("POST", "/reservations/" + id + "/confirmation", null).body());
 97	        assertEquals("CONFIRMED", confirmed.get("status").asText());
 98	        assertEquals(779.80, confirmed.get("amountPaid").asDouble());
 99	
100	        JsonNode messages = MAPPER.readTree(call("GET", "/messages", null).body());
101	        assertEquals(before + 3, messages.size());
102	        String all = messages.toString();
103	        assertTrue(all.contains("Reserva confirmada - Pousada Maré Alta"));
104	        assertTrue(all.contains("governanca@pousadamarealta.com.br"));
105	        assertTrue(all.contains("Reserva confirmada - quarto 201"));
106	        assertTrue(all.contains("financeiro@pousadamarealta.com.br"));
107	        assertTrue(all.contains("Pagamento recebido - reserva " + id));
108	
109	        assertEquals(409, call("POST", "/reservations/" + id + "/confirmation", null).statusCode());
110	    }
