112	    @Test
113	    void cancellationRules() throws Exception {
114	        long pending = create(202, "2030-04-10", "2030-04-12", 2, "STANDARD").get("id").asLong();
115	        int before = MAPPER.readTree(call("GET", "/messages", null).body()).size();
116	        JsonNode cancelled = MAPPER.readTree(call("POST", "/reservations/" + pending + "/cancellation", null).body());
117	        assertEquals("CANCELLED", cancelled.get("status").asText());
118	        assertEquals(0.0, cancelled.get("refund").asDouble());
119	        assertEquals(before, MAPPER.readTree(call("GET", "/messages", null).body()).size());
120	
121	        long paid = create(202, "2030-04-10", "2030-04-12", 2, "STANDARD").get("id").asLong();
122	        call("POST", "/reservations/" + paid + "/confirmation", null);
123	        before = MAPPER.readTree(call("GET", "/messages", null).body()).size();
124	        call("POST", "/reservations/" + paid + "/cancellation", null);
125	        String all = MAPPER.readTree(call("GET", "/messages", null).body()).toString();
126	        assertEquals(before + 2, MAPPER.readTree(call("GET", "/messages", null).body()).size());
127	        assertTrue(all.contains("Reserva cancelada - quarto 202"));
128	        assertTrue(all.contains("Reembolso - reserva " + paid));
129	
130	        long locked = create(202, "2030-05-10", "2030-05-12", 2, "NON_REFUNDABLE").get("id").asLong();
131	        call("POST", "/reservations/" + locked + "/confirmation", null);
132	        before = MAPPER.readTree(call("GET", "/messages", null).body()).size();
133	        JsonNode c = MAPPER.readTree(call("POST", "/reservations/" + locked + "/cancellation", null).body());
134	        assertEquals(0.0, c.get("refund").asDouble());
135	        assertEquals(before + 1, MAPPER.readTree(call("GET", "/messages", null).body()).size());
136	        assertEquals(409, call("POST", "/reservations/" + locked + "/cancellation", null).statusCode());
137	    }
