139	    @Test
140	    void errorsAndLifecycleAndReports() throws Exception {
141	        assertEquals(400, call("POST", "/reservations", "not json").statusCode());
142	        assertEquals("INVALID_REQUEST",
143	                errorOf(call("POST", "/reservations", reservation(101, "2031-01-12", "2031-01-10", 1, "STANDARD"))));
144	        assertEquals("INVALID_REQUEST",
145	                errorOf(call("POST", "/reservations", reservation(101, "2031-01-10", "2031-01-12", 0, "STANDARD"))));
146	        assertEquals("ROOM_NOT_FOUND",
147	                errorOf(call("POST", "/reservations", reservation(999, "2031-01-10", "2031-01-12", 1, "STANDARD"))));
148	        assertEquals("CAPACITY_EXCEEDED",
149	                errorOf(call("POST", "/reservations", reservation(101, "2031-01-10", "2031-01-12", 3, "STANDARD"))));
150	        assertEquals("RESERVATION_NOT_FOUND", errorOf(call("GET", "/reservations/99999", null)));
151	
152	        long id = create(101, "2031-01-10", "2031-01-12", 2, "NON_REFUNDABLE").get("id").asLong();
153	        assertEquals("ROOM_UNAVAILABLE",
154	                errorOf(call("POST", "/reservations", reservation(101, "2031-01-11", "2031-01-13", 1, "STANDARD"))));
155	        create(101, "2031-01-12", "2031-01-13", 1, "STANDARD"); // sai num dia, entra no mesmo
156	
157	        assertEquals(409, call("GET", "/reservations/" + id + "/document", null).statusCode());
158	        assertEquals(409, call("POST", "/reservations/" + id + "/check-in", null).statusCode());
159	        call("POST", "/reservations/" + id + "/confirmation", null);
160	        assertEquals(200, call("GET", "/reservations/" + id + "/document", null).statusCode());
161	
162	        String occupancy = call("GET", "/reports/occupancy?date=2031-01-11", null).body();
163	        assertTrue(occupancy.startsWith("room,type,reservation,check_in,check_out\n101,STANDARD," + id
164	                + ",2031-01-10,2031-01-12\ntotal,1/5"), occupancy);
165	        assertTrue(call("GET", "/reports/occupancy?date=2031-01-12", null).body().contains("total,0/5"));
166	        assertEquals(400, call("GET", "/reports/occupancy?date=2031-1-12", null).statusCode());
167	
168	        call("POST", "/reservations/" + id + "/check-in", null);
169	        JsonNode receipt = MAPPER.readTree(call("POST", "/reservations/" + id + "/check-out", null).body());
170	        assertEquals("Comprovante de reserva", receipt.get("title").asText());
171	        assertEquals(0.15 * 2 * 299.88, receipt.get("discount").asDouble(), 0.01);
172	
173	        String revenue = call("GET", "/reports/revenue?month=2031-01", null).body();
174	        assertTrue(revenue.startsWith("reservation,room,check_in,check_out,status,amount\n" + id
175	                + ",101,2031-01-10,2031-01-12,CHECKED_OUT,509.80\ntotal,509.80"), revenue);
176	        assertEquals(400, call("GET", "/reports/revenue?month=2031-13", null).statusCode());
177	    }
