201	    @Test
202	    void highSeasonNightsCostTwentyPercentMore() {
203	        Quote q = Quote.of(STANDARD, LocalDate.of(2027, 7, 10), LocalDate.of(2027, 7, 12), RatePlan.STANDARD);
204	        assertEquals(2, q.nights());
205	        assertEquals(new BigDecimal("599.76"), q.total());
206	    }
