208	    @Test
209	    void seasonBoundaries() {
210	        assertFalse(Season.isHigh(LocalDate.of(2027, 12, 14)));
211	        assertTrue(Season.isHigh(LocalDate.of(2027, 12, 15)));
212	        assertTrue(Season.isHigh(LocalDate.of(2028, 2, 29)));
213	        assertFalse(Season.isHigh(LocalDate.of(2027, 3, 1)));
214	        assertFalse(Season.isHigh(LocalDate.of(2027, 8, 1)));
